const entries=[
{id:"solar-system",cat:"space",title:"The Solar System",deck:"Our planetary neighbourhood is a dynamic system built around one star.",tags:"sun planets orbit asteroid comets",body:["The Solar System consists of the Sun and all objects gravitationally bound to it, including eight planets, their moons, dwarf planets, asteroids and comets. The Sun contains most of the system's mass and provides the energy that drives many processes on Earth.","The planets are commonly grouped into rocky inner planets — Mercury, Venus, Earth and Mars — and giant outer planets: Jupiter, Saturn, Uranus and Neptune. Between Mars and Jupiter lies the main asteroid belt. Far beyond Neptune is the Kuiper Belt, a region containing icy bodies including Pluto.","The Solar System formed about 4.6 billion years ago from a collapsing cloud of gas and dust. The planets formed from material in the rotating disk around the young Sun."],sources:[["NASA Solar System Exploration","https://science.nasa.gov/solar-system/"]]},
{id:"sun",cat:"space",title:"The Sun",deck:"The star at the centre of our Solar System.",tags:"star nuclear fusion photosphere corona",body:["The Sun is a star: a huge sphere of hot plasma held together by gravity. Its energy is produced mainly by nuclear fusion in the core, where hydrogen nuclei combine to form helium and release energy.","Energy travels outward through the Sun and eventually escapes as sunlight. The visible surface is called the photosphere; above it lie the chromosphere and the extremely hot corona. Solar activity includes sunspots, flares and coronal mass ejections.","The Sun's gravity keeps planets and many smaller bodies in orbit. Its light and heat make life as we know it possible on Earth."],sources:[["NASA — The Sun","https://science.nasa.gov/sun/"]]},
{id:"black-holes",cat:"space",title:"Black Holes",deck:"Regions of spacetime where gravity is so strong that nothing inside the event horizon can escape.",tags:"gravity event horizon spacetime astronomy",body:["A black hole forms when a large amount of matter is compressed into a sufficiently small region. Its defining boundary is the event horizon: once something crosses this boundary, it cannot return to the outside universe.","Black holes are not cosmic vacuum cleaners. From far away, their gravity behaves like that of any other object with the same mass. They can be detected through effects on nearby matter, the motion of stars, gravitational waves and radiation from hot material around them.","Astronomers identify several classes, including stellar-mass black holes and supermassive black holes found at the centres of many galaxies. The first image of a black hole's shadow was released in 2019 by the Event Horizon Telescope collaboration."],sources:[["NASA — Black Holes","https://science.nasa.gov/universe/black-holes/"],["Event Horizon Telescope","https://eventhorizontelescope.org/"]]},
{id:"venus",cat:"space",title:"Venus: A World of Extremes",deck:"A planet with crushing atmospheric pressure, intense heat and an unusual rotation.",tags:"planet atmosphere rotation greenhouse",body:["Venus is the second planet from the Sun and is similar to Earth in size, but its environment is radically different. Its dense atmosphere is mostly carbon dioxide, with clouds of sulfuric acid droplets.","A powerful greenhouse effect makes Venus the hottest planet in the Solar System. Surface temperatures are hot enough to melt lead, and atmospheric pressure at the surface is more than 90 times Earth's sea-level pressure.","Venus rotates very slowly and in the direction opposite to the rotation of most planets. One Venusian rotation takes longer than one Venusian year."],sources:[["NASA — Venus","https://science.nasa.gov/venus/"]]},
{id:"milky-way",cat:"space",title:"The Milky Way Galaxy",deck:"The barred spiral galaxy that contains our Solar System.",tags:"galaxy stars black hole universe",body:["The Milky Way is a barred spiral galaxy containing hundreds of billions of stars, along with gas, dust and dark matter. From Earth, we see its disk as a hazy band of light across a dark sky.","Our Solar System lies in a smaller structure called the Orion Arm, roughly 26,000 light-years from the galactic centre. At the centre is a supermassive black hole known as Sagittarius A*.","The Milky Way is part of the Local Group, a collection of galaxies that includes the Andromeda Galaxy and the Triangulum Galaxy."],sources:[["NASA — The Milky Way","https://science.nasa.gov/universe/galaxies/"]]},
{id:"exoplanets",cat:"space",title:"Exoplanets",deck:"Worlds orbiting stars beyond our Sun.",tags:"planet habitable zone transit astronomy",body:["An exoplanet is a planet outside our Solar System. Thousands have been confirmed, and they span a remarkable range: giant planets close to their stars, rocky worlds, planets with unusual orbits and systems with multiple planets.","Many are discovered by the transit method. When a planet passes in front of its star from our viewpoint, the star's measured brightness dips slightly. Other methods include measuring a star's motion caused by a planet's gravity.","Finding a planet in a star's habitable zone does not prove it hosts life. Atmosphere, geology, stellar activity and many other factors matter when assessing whether a world could support liquid water."],sources:[["NASA Exoplanet Exploration","https://science.nasa.gov/exoplanets/"]]},
{id:"atoms",cat:"science",title:"Atoms",deck:"The basic units of ordinary chemical elements.",tags:"protons neutrons electrons nucleus chemistry",body:["Atoms are the basic units of chemical elements. Each atom has a tiny, dense nucleus containing protons and usually neutrons, surrounded by electrons occupying quantum states.","The number of protons — the atomic number — defines the element. Atoms of the same element can have different numbers of neutrons; these forms are called isotopes.","Atoms are mostly empty space in the sense that the nucleus is extremely small compared with the overall scale of the electron cloud. Their behaviour is described by quantum mechanics."],sources:[["OpenStax Chemistry 2e","https://openstax.org/details/books/chemistry-2e"]]},
{id:"dna",cat:"life",title:"DNA: The Code of Life",deck:"A molecule that stores hereditary information in almost all living organisms.",tags:"genetics genes chromosomes double helix",body:["Deoxyribonucleic acid, or DNA, is a molecule that carries genetic information. In many organisms it is arranged as a double helix made of two complementary strands.","DNA is built from four kinds of nucleotide bases: adenine, thymine, cytosine and guanine. In the usual base-pairing pattern, adenine pairs with thymine and cytosine pairs with guanine.","Sections of DNA that contribute to functional products are called genes. Cells use genetic information in complex processes that help produce proteins and regulate development and function."],sources:[["NHGRI — DNA","https://www.genome.gov/genetics-glossary/Deoxyribonucleic-Acid"]]},
{id:"cells",cat:"life",title:"The Cell",deck:"The smallest structural and functional unit of life.",tags:"cell membrane organelles nucleus mitochondria",body:["All known living organisms are made of one or more cells. Some organisms, such as many bacteria, consist of a single cell; plants and animals are multicellular and contain specialised cell types.","A cell membrane separates the cell from its surroundings and controls what enters and leaves. Eukaryotic cells contain membrane-bound structures called organelles, including a nucleus that houses most of the cell's DNA.","Cells obtain and use energy, maintain internal conditions, respond to their environment and reproduce. Cell theory is a foundation of modern biology."],sources:[["OpenStax Biology 2e","https://openstax.org/details/books/biology-2e"]]},
{id:"human-brain",cat:"life",title:"The Human Brain",deck:"A complex organ that coordinates thought, sensation, movement and many body functions.",tags:"nervous system neurons cognition memory",body:["The brain is part of the central nervous system, together with the spinal cord. It receives information from the body and environment, processes it and helps coordinate responses.","Neurons communicate through electrical and chemical signals. Networks of neurons support functions such as movement, perception, learning, memory, language and decision-making.","The brain is not a single-purpose control centre: different regions and networks contribute to functions, and many abilities emerge through their cooperation."],sources:[["NINDS — Brain Basics","https://www.ninds.nih.gov/health-information/public-education/brain-basics"]]},
{id:"photosynthesis",cat:"life",title:"Photosynthesis",deck:"How plants, algae and some bacteria convert light energy into chemical energy.",tags:"chlorophyll plants carbon dioxide glucose oxygen",body:["Photosynthesis is a set of processes by which organisms use light energy to build energy-rich molecules. In plants, it takes place mainly in chloroplasts, which contain the pigment chlorophyll.","In oxygen-producing photosynthesis, light energy helps convert carbon dioxide and water into carbohydrates, while oxygen is released. The process supports most food webs and contributes to the oxygen in Earth's atmosphere.","Photosynthesis has two broad stages: light-dependent reactions and the Calvin cycle. These processes are linked, but they occur through different reactions and molecular machinery."],sources:[["OpenStax Biology 2e — Photosynthesis","https://openstax.org/details/books/biology-2e"]]},
{id:"evolution",cat:"life",title:"Evolution by Natural Selection",deck:"A central scientific explanation for the diversity and adaptation of life.",tags:"natural selection variation inheritance adaptation",body:["Evolution is change in heritable characteristics of populations across generations. It explains both the shared ancestry of living organisms and the diversity seen among them.","Natural selection occurs when heritable variations influence survival or reproductive success in a particular environment. Over generations, variants associated with greater reproductive success can become more common.","Evolution is supported by multiple lines of evidence, including fossils, comparative anatomy, genetics, biogeography and directly observed changes in populations."],sources:[["Understanding Evolution — UC Berkeley","https://evolution.berkeley.edu/"]]},
{id:"earth-layers",cat:"earth",title:"Inside the Earth",deck:"Our planet is structured into layers with different compositions and physical behaviours.",tags:"crust mantle outer core inner core geology",body:["Earth's interior is commonly described as the crust, mantle, outer core and inner core. The crust is the thin, solid outer layer on which continents and ocean basins sit.","The mantle is mostly solid rock that can slowly flow over geological timescales. The liquid outer core, made mainly of iron and nickel, helps generate Earth's magnetic field. The inner core is solid because of the immense pressure.","Scientists infer the structure of Earth's interior largely by studying seismic waves produced by earthquakes."],sources:[["USGS — Earth's Interior","https://www.usgs.gov/programs/earthquake-hazards/science/earths-interior"]]},
{id:"oceans",cat:"earth",title:"Earth's Oceans",deck:"A connected global ocean that shapes climate and supports extraordinary ecosystems.",tags:"ocean currents marine life deep sea climate",body:["Earth has one interconnected global ocean, conventionally divided into the Pacific, Atlantic, Indian, Southern and Arctic oceans. The ocean covers about 71 percent of the planet's surface.","Oceans absorb and redistribute heat, influence weather and climate, store carbon and provide habitats for an immense range of organisms. Ocean currents are driven by wind, differences in water density, tides and other forces.","The deep ocean includes environments with high pressure, low temperatures and no sunlight. Hydrothermal vents show that some ecosystems can rely on chemical energy rather than sunlight."],sources:[["NOAA — Ocean","https://oceanservice.noaa.gov/"]]},
{id:"climate",cat:"earth",title:"Earth's Climate System",deck:"The long-term patterns shaped by atmosphere, oceans, land, ice and living things.",tags:"climate greenhouse gases carbon warming",body:["Weather describes short-term atmospheric conditions; climate describes patterns and averages over longer periods, typically decades. Earth's climate is shaped by interactions among the atmosphere, oceans, land, ice and biosphere.","Greenhouse gases such as carbon dioxide, methane and water vapour absorb and emit infrared radiation, helping keep Earth's surface warmer than it would otherwise be. Human activities have increased concentrations of several greenhouse gases.","Climate change affects temperatures, rainfall patterns, sea level, ice and ecosystems. Scientific assessments compare observations, physical understanding and model projections to evaluate these changes."],sources:[["NASA — Climate Change","https://science.nasa.gov/climate-change/"],["IPCC","https://www.ipcc.ch/"]]},
{id:"ancient-egypt",cat:"history",title:"Ancient Egypt",deck:"A long-lived civilisation that developed along the Nile in northeastern Africa.",tags:"pharaoh pyramids nile hieroglyphs",body:["Ancient Egyptian civilisation flourished along the Nile, whose annual flooding supported agriculture and settlement. Its history spans thousands of years and includes periods of political unity, fragmentation and foreign rule.","Egyptian society developed distinctive systems of writing, art, architecture, religion and administration. Monumental tombs and temples, including the pyramids at Giza, remain important archaeological sites.","Ancient Egypt was not static: beliefs, political structures and cultural practices changed over time and varied across regions and periods."],sources:[["The Metropolitan Museum of Art — Ancient Egypt","https://www.metmuseum.org/toah/hd/egyp/hd_egyp.htm"]]},
{id:"indus-valley",cat:"history",title:"Indus Valley Civilisation",deck:"One of the world's earliest urban civilisations, flourishing in South Asia.",tags:"harappa mohenjo daro south asia archaeology",body:["The Indus or Harappan Civilisation flourished across parts of present-day Pakistan and northwestern India during the third millennium BCE, with roots and later phases extending beyond its mature urban period.","Major sites such as Harappa and Mohenjo-daro reveal planned streets, drainage systems, craft production and long-distance trade. The civilisation covered a large and diverse region rather than a single city-state.","Its script has not yet been conclusively deciphered, so many details about its political organisation, languages and beliefs remain uncertain. Archaeological interpretations continue to develop as new evidence is studied."],sources:[["Harappa.com — Research and Resources","https://www.harappa.com/"]]},
{id:"printing-press",cat:"history",title:"The Printing Press",deck:"A technology that transformed the speed and scale of information sharing.",tags:"gutenberg books movable type history",body:["Movable-type printing existed in East Asia before Johannes Gutenberg's fifteenth-century work in Europe. Gutenberg's press helped make the production of books in Europe faster and more repeatable.","Printing reduced the cost and time required to reproduce texts, supporting the spread of religious, scientific, political and literary ideas. Its effects depended on literacy, institutions, languages and access to materials.","The printing revolution was not a single isolated invention; it built on earlier developments in paper-making, ink, metalworking and printing technologies."],sources:[["British Library — Gutenberg and the Printing Revolution","https://www.bl.uk/learning/timeline/item107644.html"]]},
{id:"mahabharata",cat:"mythology",title:"The Mahabharata",deck:"One of the major Sanskrit epics of India, exploring duty, kinship, conflict and ethics.",tags:"india epic pandavas kauravas bhagavad gita",body:["The Mahabharata is a vast Sanskrit epic traditionally attributed to Vyasa. Its central narrative concerns conflict between related branches of the Kuru family, the Pandavas and the Kauravas.","The work includes philosophical and devotional material, most famously the Bhagavad Gita, a dialogue between Krishna and Arjuna before the great battle. It explores dharma, duty, justice, action and the complexity of moral choices.","The epic developed over a long period and exists in many regional and retold forms. It is both a literary tradition and a living source of cultural and religious meaning for many communities."],sources:[["Encyclopaedia Britannica — Mahabharata","https://www.britannica.com/topic/Mahabharata"]]},
{id:"ramayana",cat:"mythology",title:"The Ramayana",deck:"An influential Indian epic with many regional and cultural retellings.",tags:"rama sita hanuman ayodhya epic",body:["The Ramayana tells the story of Rama, Sita, Lakshmana and Hanuman, including Rama's exile, Sita's abduction by Ravana and the effort to bring her home. The Sanskrit version is traditionally attributed to Valmiki.","The epic has inspired extensive retellings across South and Southeast Asia in literature, performance, visual art and popular culture. These versions differ in language, emphasis and detail.","The Ramayana is studied as literature and history of ideas, and is also revered as a sacred narrative by many people. Interpretations vary across communities and traditions."],sources:[["Encyclopaedia Britannica — Ramayana","https://www.britannica.com/topic/Ramayana"]]},
{id:"greek-mythology",cat:"mythology",title:"Greek Mythology",deck:"A diverse body of stories about gods, heroes, origins and the human condition.",tags:"zeus athena olympus heracles myths",body:["Greek mythology consists of stories developed in ancient Greek-speaking communities about gods, heroes, the origins of the world and the relationship between humans and the divine.","The Olympian gods, including Zeus, Hera, Athena and Apollo, appear in many myths, but traditions varied by region and period. Myths were preserved through poetry, drama, art, ritual and local storytelling.","Ancient Greek myths influenced later Roman culture and have had a lasting impact on literature, art, philosophy and popular storytelling."],sources:[["Theoi Greek Mythology","https://www.theoi.com/"]]},
{id:"ai",cat:"technology",title:"Artificial Intelligence",deck:"Computer systems designed to perform tasks that typically require aspects of human intelligence.",tags:"machine learning neural networks generative ai",body:["Artificial intelligence is a broad field concerned with building systems that perform tasks such as recognising patterns, understanding language, making predictions and generating content.","Machine learning is one major approach: systems learn statistical patterns from data rather than relying only on hand-written rules. Deep learning uses multi-layer neural networks and has enabled major progress in image, speech and language tasks.","AI systems have limitations. They can make errors, reflect biases in data and produce confident-sounding but incorrect outputs. Human oversight, evaluation, transparency and responsible deployment are important."],sources:[["Stanford Encyclopedia of Philosophy — Artificial Intelligence","https://plato.stanford.edu/entries/artificial-intelligence/"],["NIST AI Risk Management Framework","https://www.nist.gov/itl/ai-risk-management-framework"]]},
{id:"internet",cat:"technology",title:"How the Internet Works",deck:"A global network of networks that exchange data using shared protocols.",tags:"tcp ip dns routers packets web",body:["The internet is a global system of interconnected computer networks. Devices exchange data using agreed protocols, especially the Internet Protocol suite, which includes IP, TCP and other standards.","When you visit a website, your device may use the Domain Name System to translate a human-readable domain name into an IP address. Data is divided into packets that travel through networks and are reassembled at their destination.","The World Wide Web is one service that runs on the internet. Email, file transfer, messaging and many other services also use the underlying network."],sources:[["Cloudflare Learning Center — What is the Internet?","https://www.cloudflare.com/learning/network-layer/what-is-the-internet/"]]},
{id:"quantum",cat:"science",title:"Quantum Mechanics",deck:"The framework physicists use to describe matter and energy at very small scales.",tags:"wave particle uncertainty superposition physics",body:["Quantum mechanics is the physical theory used to describe atoms, electrons, photons and other microscopic systems. It differs from everyday classical intuition and makes predictions in terms of probabilities.","Quantum states can show superposition, and measurements are described by mathematical rules that predict possible outcomes. The uncertainty principle places limits on how precisely certain pairs of properties can be known together.","Quantum theory underpins technologies including semiconductors, lasers, magnetic resonance imaging and many modern sensors."],sources:[["NIST — Quantum Science","https://www.nist.gov/quantum-information-science"]]},
{id:"deep-ocean",cat:"mysteries",title:"The Deep Ocean",deck:"A vast, challenging environment that scientists are still exploring.",tags:"abyss hadal trench exploration marine",body:["The deep sea is commonly used for ocean regions below the depth reached by sunlight. It includes the dark water column, seafloor plains, underwater mountains and deep trenches.","Exploration is difficult because of immense pressure, cold temperatures, darkness and distance from the surface. Researchers use remotely operated vehicles, autonomous vehicles, sonar and specialised instruments to study it.","New species and geological features continue to be documented. The deep ocean is not entirely unknown, but it remains much less directly observed than the land surface."],sources:[["NOAA Ocean Exploration","https://oceanexplorer.noaa.gov/"]]},
{id:"aurora",cat:"mysteries",title:"Auroras",deck:"Natural light displays produced when charged particles interact with Earth's upper atmosphere.",tags:"northern lights southern lights solar wind magnetosphere",body:["Auroras occur when charged particles, often originating from the Sun, are guided by Earth's magnetic field toward the polar regions. There they interact with atoms and molecules in the upper atmosphere.","These collisions transfer energy to atmospheric gases. As the gases return to lower-energy states, they emit light at characteristic colours. Oxygen commonly contributes green and red emissions, while nitrogen can produce blue and purple hues.","Auroras are known as the aurora borealis in the north and aurora australis in the south. Their intensity often increases during periods of heightened solar activity."],sources:[["NASA — Aurora","https://science.nasa.gov/heliophysics/focus-areas/aurora/"]]},
{id:"newton-laws",cat:"physics",title:"Newton's Laws of Motion",deck:"Three principles that connect forces with the motion of objects.",tags:"force inertia acceleration mechanics physics",body:["Newton's first law says that an object remains at rest or continues moving at constant velocity unless a net external force acts on it. This tendency to resist changes in motion is called inertia.","The second law relates net force, mass and acceleration: for constant mass, net force equals mass multiplied by acceleration. The third law says that when one object exerts a force on another, the second exerts an equal and opposite force on the first. These laws are foundational to classical mechanics."],sources:[["OpenStax University Physics — Newton's Laws","https://openstax.org/details/books/university-physics-volume-1"]]},
{id:"electromagnetism",cat:"physics",title:"Electricity and Magnetism",deck:"Electric and magnetic phenomena are two connected aspects of electromagnetism.",tags:"electric charge current magnetic field maxwell",body:["Electric charge is a property of matter that produces electric interactions. Moving charges form electric currents, and currents can create magnetic fields. Changing magnetic fields can in turn induce electric fields.","Maxwell's equations describe how electric and magnetic fields are generated and interact. Electromagnetism explains circuits, motors, generators, radio waves, light and many technologies used in everyday life."],sources:[["OpenStax University Physics — Electromagnetism","https://openstax.org/details/books/university-physics-volume-2"]]},
{id:"thermodynamics",cat:"physics",title:"The Laws of Thermodynamics",deck:"Rules describing energy, heat, temperature and the direction of physical processes.",tags:"energy entropy heat temperature thermodynamics",body:["The first law expresses conservation of energy: energy can be transferred or transformed, but the total energy of an isolated system remains constant. The second law introduces entropy and explains why natural processes have a preferred direction.","The third law describes the behaviour of entropy as temperature approaches absolute zero. Thermodynamics helps explain engines, refrigerators, chemical reactions, stars and biological energy transfers."],sources:[["OpenStax Chemistry 2e — Thermodynamics","https://openstax.org/details/books/chemistry-2e"]]},
{id:"periodic-table",cat:"chemistry",title:"The Periodic Table",deck:"A map of chemical elements arranged by atomic number and recurring properties.",tags:"elements groups periods atomic number chemistry",body:["The modern periodic table arranges elements in order of increasing atomic number, the number of protons in an atom's nucleus. Rows are called periods and columns are called groups.","Elements in the same group often share patterns in their chemical behaviour because of their electron arrangements. The table helps scientists organise known elements and predict properties of substances and compounds."],sources:[["IUPAC — Periodic Table","https://iupac.org/what-we-do/periodic-table-of-elements/"]]},
{id:"chemical-bonds",cat:"chemistry",title:"Chemical Bonds",deck:"The interactions that hold atoms together in molecules and extended structures.",tags:"ionic covalent metallic electrons chemistry",body:["Chemical bonds arise from interactions involving electrons and atomic nuclei. In a covalent bond, atoms share electron pairs; in an ionic interaction, oppositely charged ions attract after electron transfer; metallic bonding involves delocalised electrons across a structure.","Bonding influences the shape, stability, reactivity and physical properties of substances. Real materials can show bonding with a mixture of ionic, covalent and metallic characteristics."],sources:[["OpenStax Chemistry 2e — Chemical Bonding","https://openstax.org/details/books/chemistry-2e"]]},
{id:"acids-bases",cat:"chemistry",title:"Acids, Bases and pH",deck:"A framework for understanding proton transfer and acidity in solutions.",tags:"acid base ph neutralisation chemistry",body:["In the Brønsted–Lowry model, an acid donates a proton and a base accepts a proton. In water, the pH scale is commonly used to describe acidity: lower pH indicates greater hydrogen-ion activity, while higher pH indicates more basic conditions.","Acids and bases participate in neutralisation reactions and are important in digestion, soil chemistry, industry, water treatment and biological systems. The pH scale is logarithmic, so a change of one pH unit represents a tenfold change in hydrogen-ion activity."],sources:[["OpenStax Chemistry 2e — Acids and Bases","https://openstax.org/details/books/chemistry-2e"]]},
{id:"prime-numbers",cat:"mathematics",title:"Prime Numbers",deck:"Whole numbers greater than one that have exactly two positive divisors.",tags:"prime factorisation number theory mathematics",body:["A prime number is an integer greater than one whose only positive divisors are one and itself. Numbers greater than one that are not prime are called composite numbers.","Every integer greater than one can be expressed as a product of primes in essentially one unique way, apart from the order of factors. This is the fundamental theorem of arithmetic. Prime numbers are important in number theory and modern cryptography."],sources:[["Wolfram MathWorld — Prime Number","https://mathworld.wolfram.com/PrimeNumber.html"]]},
{id:"calculus",cat:"mathematics",title:"What Is Calculus?",deck:"The mathematics of change, motion and accumulation.",tags:"derivative integral limits mathematics",body:["Calculus has two central ideas. Differential calculus studies rates of change using derivatives, while integral calculus studies accumulation, areas and quantities built from small contributions.","The fundamental theorem of calculus connects differentiation and integration. These tools are used in physics, engineering, economics, biology, computer science and many other fields to model changing systems."],sources:[["OpenStax Calculus Volume 1","https://openstax.org/details/books/calculus-volume-1"]]},
{id:"probability",cat:"mathematics",title:"Probability and Statistics",deck:"Tools for reasoning about uncertainty and learning from data.",tags:"chance data distributions statistics probability",body:["Probability assigns numerical measures to the likelihood of events, from zero for an impossible event to one for a certain event. Statistical methods use data to describe patterns, estimate unknown quantities and test claims.","A sample is used to learn about a larger population, but sampling methods and uncertainty matter. Good statistical reasoning considers variation, possible bias, sample size and the limits of conclusions."],sources:[["OpenStax Introductory Statistics","https://openstax.org/details/books/introductory-statistics"]]},
{id:"vaccines",cat:"medicine",title:"How Vaccines Work",deck:"Vaccines train the immune system to recognise specific infectious threats.",tags:"immunity antibodies antigen public health medicine",body:["Vaccines expose the immune system to an antigen or instructions for making one, without requiring a person to experience the disease in the usual way. This can help the body develop immune memory involving cells and antibodies.","If the vaccinated person later encounters the pathogen, immune responses may act more quickly and reduce the risk of severe illness. Vaccine types differ, and recommendations depend on age, health, location and current public-health guidance."],sources:[["WHO — Vaccines and Immunization","https://www.who.int/health-topics/vaccines-and-immunization"]]},
{id:"human-heart",cat:"medicine",title:"The Human Heart",deck:"A muscular pump that circulates blood through the lungs and the rest of the body.",tags:"cardiovascular circulation arteries veins heart",body:["The heart has four chambers: two atria and two ventricles. The right side sends blood to the lungs for gas exchange, while the left side pumps oxygenated blood through the systemic circulation.","Valves help keep blood moving in the correct direction. The heartbeat is coordinated by electrical signals within cardiac tissue. The circulatory system transports oxygen, nutrients, hormones and waste products throughout the body."],sources:[["NHLBI — How the Heart Works","https://www.nhlbi.nih.gov/health/heart/how-heart-works"]]},
{id:"antibiotics",cat:"medicine",title:"Antibiotics and Antibiotic Resistance",deck:"Medicines that target bacteria—and why they must be used responsibly.",tags:"bacteria infection antimicrobial resistance health",body:["Antibiotics are medicines used to treat certain bacterial infections. They work through different mechanisms, such as interfering with bacterial cell-wall formation or protein production. They do not treat viral infections such as the common cold.","Antimicrobial resistance can develop when microbes evolve traits that allow them to survive medicines. Appropriate prescribing, taking medicines as directed by a qualified professional and infection prevention all help reduce the spread of resistant organisms."],sources:[["WHO — Antimicrobial Resistance","https://www.who.int/news-room/fact-sheets/detail/antimicrobial-resistance"]]},
{id:"memory-learning",cat:"psychology",title:"How Human Memory Works",deck:"Memory involves encoding, storing and retrieving information.",tags:"brain learning recall cognition psychology",body:["Memory is not a single storage box. Researchers study processes such as encoding information, maintaining it over time and retrieving it when needed. Different forms include working memory, episodic memory, semantic memory and procedural memory.","Remembering is reconstructive: details can change and confidence does not always guarantee accuracy. Sleep, attention, prior knowledge, emotion and repeated practice can influence learning and recall."],sources:[["American Psychological Association — Memory","https://www.apa.org/topics/memory"]]},
{id:"cognitive-bias",cat:"psychology",title:"Cognitive Biases",deck:"Predictable patterns that can influence how people interpret information and make decisions.",tags:"decision making confirmation bias psychology",body:["A cognitive bias is a systematic tendency in thinking that can affect judgement. Confirmation bias, for example, involves favouring information that supports an existing belief while giving less attention to conflicting evidence.","Biases are not proof that people cannot reason well. Awareness, checking evidence, considering alternatives and slowing down important decisions can improve judgement. Researchers study biases in specific contexts rather than treating every shortcut as automatically harmful."],sources:[["Stanford Encyclopedia of Philosophy — Bias","https://plato.stanford.edu/entries/implicit-bias/"]]},
{id:"sleep-science",cat:"psychology",title:"The Science of Sleep",deck:"Sleep is an active biological process important for learning, health and daily functioning.",tags:"circadian rhythm REM memory rest psychology",body:["Sleep occurs in repeating cycles that include non-rapid eye movement and rapid eye movement stages. Brain activity, breathing and other body processes change across these stages during the night.","Sleep supports attention, memory, emotional regulation and physical health. Circadian rhythms help coordinate sleep and wakefulness with the day-night cycle, while light, routines, stress and health can influence sleep patterns."],sources:[["NHLBI — Sleep Deprivation and Deficiency","https://www.nhlbi.nih.gov/health/sleep-deprivation"]]},
{id:"tectonic-plates",cat:"geography",title:"Plate Tectonics",deck:"The movement of Earth's outer shell shapes continents, mountains and ocean basins.",tags:"earthquakes volcanoes continents geology geography",body:["Earth's lithosphere is divided into large and small tectonic plates that move slowly over the softer, slowly deforming mantle below. Plates can move apart, collide or slide past one another.","Plate interactions help explain the distribution of many earthquakes, volcanoes, mountain belts and ocean trenches. The theory of plate tectonics unifies observations from geology, geophysics, oceanography and the study of Earth's history."],sources:[["USGS — This Dynamic Earth","https://pubs.usgs.gov/gip/dynamic/"]]},
{id:"world-climate-zones",cat:"geography",title:"World Climate Zones",deck:"Climate regions differ in temperature, rainfall and seasonal patterns.",tags:"tropics desert temperate polar geography",body:["Climate classification systems group places using long-term patterns of temperature and precipitation. Broad categories include tropical, dry, temperate, continental and polar climates, with many subtypes.","Climate zones influence ecosystems, agriculture, settlement and architecture, but local conditions also depend on elevation, distance from oceans, winds and geography. Climate is not the same as the weather experienced on a particular day."],sources:[["National Geographic Education — Climate","https://education.nationalgeographic.org/resource/climate/"]]},
{id:"maps-cartography",cat:"geography",title:"Maps and Cartography",deck:"How people represent Earth's curved surface and communicate spatial information.",tags:"map projection latitude longitude geography",body:["Cartography is the practice and study of making maps. Maps simplify the world for a purpose, such as navigation, showing terrain, planning cities or presenting population patterns.","Because Earth is approximately spherical, representing it on a flat map requires a projection. Every projection introduces some distortion in area, shape, distance or direction, so the best choice depends on what the map needs to show."],sources:[["USGS — Map Projections","https://www.usgs.gov/programs/national-geospatial-program/map-projections"]]},
{id:"biodiversity",cat:"environment",title:"Biodiversity",deck:"The variety of life at genetic, species and ecosystem levels.",tags:"ecosystems species conservation biodiversity",body:["Biodiversity includes variation within species, the diversity of species and the variety of ecosystems. It supports processes such as pollination, nutrient cycling, soil formation and the resilience of natural systems.","Habitat loss, invasive species, pollution, overexploitation and climate change place pressure on biodiversity. Conservation approaches include protected areas, habitat restoration, sustainable resource use and cooperation with local communities."],sources:[["Convention on Biological Diversity","https://www.cbd.int/"]]},
{id:"renewable-energy",cat:"environment",title:"Renewable Energy",deck:"Energy from sources that are naturally replenished on human timescales.",tags:"solar wind hydro geothermal energy",body:["Renewable energy sources include sunlight, wind, moving water, geothermal heat and sustainably managed bioenergy. Electricity systems can combine several sources, supported by transmission networks, storage and flexible demand.","Each technology has benefits and trade-offs involving land, materials, wildlife, cost, reliability and location. A balanced energy transition considers the full system rather than judging a source by one feature alone."],sources:[["International Energy Agency — Renewables","https://www.iea.org/energy-system/renewables"]]},
{id:"water-cycle",cat:"environment",title:"The Water Cycle",deck:"Water continually moves among the atmosphere, land, oceans and living things.",tags:"evaporation condensation precipitation hydrology",body:["The water cycle includes evaporation from surfaces, transpiration from plants, condensation into clouds, precipitation and the movement of water across and beneath the ground. Water can be stored in oceans, lakes, glaciers, soil and aquifers.","The cycle is powered mainly by solar energy and gravity. Human activities such as groundwater extraction, dam construction, land-use change and pollution can alter local water availability and quality."],sources:[["USGS — The Water Cycle","https://www.usgs.gov/special-topics/water-science-school/science/water-cycle"]]},
{id:"bridges",cat:"engineering",title:"How Bridges Work",deck:"Structures that carry loads across gaps while managing forces and materials.",tags:"civil engineering tension compression beams",body:["A bridge transfers loads from its deck through structural elements to supports and foundations. Engineers consider forces such as tension, compression, bending, shear, vibration and environmental loads.","Beam, arch, truss, suspension and cable-stayed bridges use different structural arrangements. Design depends on span, ground conditions, materials, traffic, climate, maintenance and safety requirements."],sources:[["PBS — Building Big","https://www.pbs.org/wgbh/buildingbig/"]]},
{id:"electric-motors",cat:"engineering",title:"Electric Motors",deck:"Machines that convert electrical energy into mechanical motion.",tags:"motor magnetic field torque engineering",body:["Many electric motors use the interaction between magnetic fields and electric currents to produce torque. A motor's rotor turns relative to a stationary stator, while the design controls how magnetic forces are produced and switched.","Electric motors power fans, pumps, appliances, industrial machinery and electric vehicles. Different motor types are selected according to needs such as speed control, efficiency, cost, reliability and maintenance."],sources:[["U.S. Department of Energy — Motors","https://www.energy.gov/eere/amo/electric-motors"]]},
{id:"semiconductors",cat:"engineering",title:"Semiconductors and Microchips",deck:"Materials whose electrical behaviour enables modern electronic devices.",tags:"silicon transistor integrated circuit electronics",body:["Semiconductors, such as silicon, have electrical properties between those of conductors and insulators. Their behaviour can be controlled by adding small amounts of other elements, applying electric fields and building carefully designed structures.","Transistors act as electronic switches or amplifiers. Billions of transistors can be integrated into modern chips, forming the basis of processors, memory, sensors and communication devices."],sources:[["NIST — Semiconductor Electronics","https://www.nist.gov/"]]},
{id:"supply-demand",cat:"economics",title:"Supply and Demand",deck:"A basic model for understanding how buyers and sellers interact in markets.",tags:"price market equilibrium economics",body:["Demand describes how much of a good or service buyers are willing and able to purchase at different prices. Supply describes how much sellers are willing and able to offer at different prices, all else equal.","In the basic model, the market price tends toward a point where quantity supplied equals quantity demanded. Real markets are influenced by factors such as income, expectations, competition, taxes, market power and changes in technology."],sources:[["CORE Econ — The Economy","https://www.core-econ.org/the-economy/"]]},
{id:"inflation",cat:"economics",title:"Inflation",deck:"A sustained rise in the general level of prices across an economy.",tags:"consumer price index purchasing power economics",body:["Inflation means that the overall price level rises over time, reducing the purchasing power of a unit of money. It is commonly measured using price indexes that track a basket of goods and services.","Inflation can be influenced by demand, production costs, supply disruptions, expectations and monetary conditions. A single price increase is not by itself the same as economy-wide inflation."],sources:[["IMF — Inflation: Prices on the Rise","https://www.imf.org/en/Publications/fandd/issues/Series/Back-to-Basics/Inflation"]]},
{id:"gdp",cat:"economics",title:"What Is GDP?",deck:"A measure of the value of final goods and services produced within an economy.",tags:"gross domestic product economy output economics",body:["Gross domestic product, or GDP, measures the market value of final goods and services produced within a country during a given period. It can be estimated through production, income or expenditure approaches.","GDP is useful for tracking economic activity, but it is not a complete measure of wellbeing. It does not by itself show how income is distributed, how unpaid work is valued or whether environmental costs are sustainable."],sources:[["World Bank — GDP","https://data.worldbank.org/indicator/NY.GDP.MKTP.CD"]]},
{id:"logic",cat:"philosophy",title:"Logic and Critical Thinking",deck:"Methods for evaluating arguments, evidence and the relationships between ideas.",tags:"reasoning argument deduction fallacy philosophy",body:["Logic studies principles of valid reasoning. In a deductive argument, if the premises are true and the reasoning is valid, the conclusion must be true. Inductive reasoning instead supports conclusions with evidence without guaranteeing them.","Critical thinking involves clarifying claims, checking sources, identifying assumptions, considering counterarguments and distinguishing evidence from opinion. A persuasive statement is not automatically a well-supported one."],sources:[["Stanford Encyclopedia of Philosophy — Logic","https://plato.stanford.edu/entries/logic-classical/"]]},
{id:"ethics",cat:"philosophy",title:"Ethics: Thinking About Right and Wrong",deck:"The branch of philosophy that examines values, duties and how people ought to act.",tags:"morality virtue justice philosophy ethics",body:["Ethics explores questions about right action, good character, justice and the values that guide individual and collective life. Major approaches include consequentialist theories, which assess outcomes; deontological theories, which emphasise duties; and virtue ethics, which focuses on character.","Ethical questions often involve competing values and incomplete information. Philosophical analysis helps make assumptions explicit and compare reasons, though people and traditions may disagree about the best answers."],sources:[["Stanford Encyclopedia of Philosophy — Ethics","https://plato.stanford.edu/entries/ethics-virtue/"]]},
{id:"democracy",cat:"civics",title:"Democracy and Citizenship",deck:"Systems of government in which people have a role in public decision-making.",tags:"elections rights constitution civic education",body:["Democracy is a form of political organisation in which public authority is connected to the people. Democracies vary, but commonly include elections, political participation, legal protections, public debate and institutions that limit or review government power.","Citizenship involves rights and responsibilities within a political community. Understanding constitutions, institutions, reliable information and peaceful participation helps people engage with public life."],sources:[["International IDEA — Democracy","https://www.idea.int/"]]},
{id:"indian-constitution",cat:"civics",title:"The Constitution of India",deck:"The foundational legal document defining India's institutions, rights and governing framework.",tags:"india constitution parliament fundamental rights civics",body:["The Constitution of India came into effect on 26 January 1950. It establishes the structure of government, distributes powers between institutions and levels of government, and sets out principles and procedures for public authority.","It includes Fundamental Rights, Directive Principles of State Policy and Fundamental Duties, among other provisions. Constitutional interpretation and amendments have shaped how the document operates over time."],sources:[["Legislative Department, Government of India","https://legislative.gov.in/constitution-of-india/"]]},
{id:"united-nations",cat:"civics",title:"The United Nations",deck:"An international organisation created to support cooperation among countries.",tags:"UN diplomacy peace development international relations",body:["The United Nations was established in 1945 after the Second World War. Its work includes international peace and security, humanitarian assistance, human rights, sustainable development and international law.","The UN system includes principal organs such as the General Assembly, Security Council, International Court of Justice and Secretariat, along with specialised agencies and programmes. Its actions depend on member states and the authority given to each body."],sources:[["United Nations — About Us","https://www.un.org/en/about-us"]]},
{id:"soil",cat:"agriculture",title:"Soil: A Living Resource",deck:"Soil supports plants, stores water and hosts diverse communities of organisms.",tags:"soil nutrients agriculture microbes fertility",body:["Soil is a complex mixture of mineral particles, organic matter, water, air and living organisms. Its properties depend on parent material, climate, organisms, topography and time.","Healthy soils help plants obtain water and nutrients, store carbon, filter water and support biodiversity. Erosion, compaction, salinisation and contamination can reduce soil quality, while careful land management can protect it."],sources:[["FAO — Soils Portal","https://www.fao.org/soils-portal/en/"]]},
{id:"crop-pollination",cat:"agriculture",title:"Pollination and Food Production",deck:"The transfer of pollen enables reproduction in many flowering plants.",tags:"pollinators bees crops agriculture biodiversity",body:["Pollination is the transfer of pollen from an anther to a receptive stigma. It can occur through wind, water or animals. Bees, butterflies, birds, bats and other animals pollinate many wild plants and crops.","Pollination supports seed and fruit production in numerous food plants. Protecting pollinators involves conserving habitats, reducing harmful pesticide exposure and maintaining diverse flowering resources across landscapes."],sources:[["FAO — Pollination","https://www.fao.org/pollination/en/"]]},
{id:"sustainable-farming",cat:"agriculture",title:"Sustainable Agriculture",deck:"Farming approaches that aim to maintain productivity while protecting natural resources.",tags:"farming soil water food systems agriculture",body:["Sustainable agriculture considers long-term soil health, water use, biodiversity, farmer livelihoods and reliable food production. Practices vary by region and may include crop rotation, integrated pest management, agroforestry and efficient irrigation.","No single method fits every farm. Good decisions depend on local climate, soils, crops, available resources, markets and the knowledge of farming communities."],sources:[["FAO — Sustainable Food and Agriculture","https://www.fao.org/sustainability/en/"]]},
{id:"poetry",cat:"literature",title:"How to Read Poetry",deck:"Poetry uses sound, imagery, rhythm and form to shape meaning.",tags:"poem metaphor imagery literature language",body:["Poetry is a literary form that often concentrates language, sound, rhythm and imagery. A poem may use metaphor, symbolism, repetition, line breaks and patterns of sound to create layers of meaning.","Reading a poem involves noticing both what it says and how it says it. Context can help, but interpretations should be supported by details in the text rather than assumptions about what the poet must have intended."],sources:[["Poetry Foundation — Learning","https://www.poetryfoundation.org/learn"]]},
{id:"world-literature",cat:"literature",title:"World Literature",deck:"Stories, poems and plays from many languages, cultures and historical periods.",tags:"novels epics drama storytelling literature",body:["World literature includes works that travel across languages and cultures through translation, adaptation, education and exchange. It ranges from oral traditions and ancient epics to contemporary novels, plays and poetry.","Comparing works across cultures can reveal shared human questions as well as different histories, values and literary forms. Translation makes literature accessible while also raising questions about style, meaning and cultural context."],sources:[["UNESCO — Literature and Culture","https://www.unesco.org/en"]]},
{id:"story-structure",cat:"literature",title:"The Elements of Storytelling",deck:"Characters, conflict, setting and structure help shape a narrative.",tags:"plot character theme narrative literature",body:["Many stories develop through characters pursuing goals while facing obstacles. Plot describes the sequence and arrangement of events; setting establishes where and when a story takes place; theme concerns ideas explored through the narrative.","Writers use point of view, pacing, dialogue, imagery and structure to guide readers' attention. These elements are flexible tools, not rigid rules: stories can experiment with chronology, voice and form."],sources:[["Purdue OWL — Fiction Basics","https://owl.purdue.edu/owl/subject_specific_writing/creative_writing/index.html"]]},
{id:"colour-theory",cat:"arts",title:"Colour Theory",deck:"A framework for understanding how colours relate and affect visual composition.",tags:"hue saturation contrast art design",body:["Colour theory studies how colours can be organised and combined. Common concepts include hue, value, saturation, complementary colours, analogous palettes and contrast. Different colour models are used for light, print and digital design.","Colour perception depends on context, lighting, surrounding colours and human vision. Designers use colour relationships to establish hierarchy, communicate information and create a particular visual atmosphere."],sources:[["Getty Education — Art and Colour","https://www.getty.edu/education/"]]},
{id:"perspective-art",cat:"arts",title:"Perspective in Drawing",deck:"Techniques that create the impression of depth on a flat surface.",tags:"vanishing point horizon line art drawing",body:["Linear perspective represents parallel lines as if they converge toward one or more vanishing points on the horizon. One-point perspective is often used for views looking directly down a straight space; two-point perspective is common for the corner of a building.","Artists also suggest depth through overlap, relative size, atmospheric perspective, texture and changes in contrast. These methods can be combined to create convincing or deliberately stylised spaces."],sources:[["National Gallery of Art — Education","https://www.nga.gov/learn.html"]]},
{id:"photography",cat:"arts",title:"The Basics of Photography",deck:"Photography combines light, timing, composition and technical choices.",tags:"camera aperture shutter iso composition",body:["A camera records light through a lens onto a sensor or photosensitive material. Exposure is commonly controlled using aperture, shutter speed and ISO sensitivity, which interact to affect brightness and image characteristics.","Composition guides how viewers read an image. Choices such as framing, viewpoint, leading lines, balance and timing can shape emphasis, while ethical photography considers consent, context and truthful representation."],sources:[["Nikon Learn and Explore","https://www.nikonusa.com/learn-and-explore"]]},
{id:"olympic-games",cat:"sports",title:"The Olympic Games",deck:"An international multi-sport event rooted in ancient and modern traditions.",tags:"olympics athletes sport history",body:["The ancient Olympic Games were held at Olympia in Greece. The modern Olympic movement began in the late nineteenth century, with the first modern Summer Games held in Athens in 1896.","Today the Olympic Games bring together athletes from many countries and include Summer and Winter editions. The movement is governed by rules and institutions, and has evolved in response to changes in sport, society and global participation."],sources:[["International Olympic Committee — Olympic Games","https://olympics.com/ioc/overview"]]},
{id:"sports-science",cat:"sports",title:"The Science of Sports Performance",deck:"Human movement combines physiology, biomechanics, psychology and skill.",tags:"exercise biomechanics training sports science",body:["Sports science studies how the body responds to physical activity and how movement skills are developed. Biomechanics examines forces and motion, while exercise physiology studies how body systems respond and adapt to activity.","Performance is influenced by technique, recovery, nutrition, sleep, environment, motivation and access to coaching. Safe training is individual and should account for age, experience and health."],sources:[["Australian Institute of Sport — Sports Science","https://www.ais.gov.au/"]]},
{id:"football",cat:"sports",title:"Football: The Global Game",deck:"A team sport played across the world under shared rules and many local traditions.",tags:"soccer FIFA teamwork tactics sport",body:["Association football is played by two teams, each aiming to score by moving the ball into the opposing goal while following rules that restrict most use of hands and arms by outfield players.","The modern Laws of the Game are maintained by the International Football Association Board. Football has many tactical approaches, from possession-based play to counterattacking systems, and is shaped by local clubs, national teams and supporter cultures."],sources:[["IFAB — Laws of the Game","https://www.theifab.com/laws/latest/"]]},
{id:"architecture",cat:"architecture",title:"What Is Architecture?",deck:"The design of buildings and spaces shaped by people, place and purpose.",tags:"buildings design structure urban architecture",body:["Architecture combines art, science and practical problem-solving to shape buildings and environments. Architects consider function, structure, materials, climate, accessibility, culture, cost and the experience of people using a space.","Architectural styles reflect changing technologies and social conditions. A building can be understood not only as an object but also as part of a street, landscape, community and wider built environment."],sources:[["Royal Institute of British Architects — Architecture","https://www.architecture.com/"]]},
{id:"sustainable-cities",cat:"architecture",title:"Sustainable Cities and Urban Design",deck:"How cities can plan buildings, transport and public spaces for long-term wellbeing.",tags:"urban planning public transport green buildings cities",body:["Urban design shapes how streets, buildings, parks and public spaces work together. Compact mixed-use neighbourhoods, safe walking and cycling routes, reliable public transport and accessible green spaces can support more liveable cities.","Sustainable planning must respond to local needs, climate risks, housing affordability, infrastructure and community participation. There is no single city model that works everywhere."],sources:[["UN-Habitat — Urban Planning","https://unhabitat.org/topic/urban-planning-and-design"]]},
{id:"architectural-history",cat:"architecture",title:"A Brief History of Architecture",deck:"Building traditions evolve with materials, beliefs, technology and society.",tags:"classical gothic modern architecture history",body:["Architectural history includes many traditions: ancient monumental structures, classical orders, South Asian temple architecture, Islamic geometric design, Gothic cathedrals, industrial-era engineering and modernist movements.","Styles do not develop in a simple straight line. They overlap, adapt and exchange ideas across regions, and buildings often combine local materials and traditions with influences from elsewhere."],sources:[["Smarthistory — Architecture","https://smarthistory.org/architecture/"]]},
{id:"music-and-sound",cat:"arts",title:"Music and the Science of Sound",deck:"How vibrations become the melodies and rhythms people hear.",tags:"sound waves frequency pitch rhythm music",body:["Sound is produced by vibrations that travel through a medium such as air, water or a solid. The frequency of a sound wave is related to perceived pitch, while amplitude is related to loudness. Musical notes are organised into patterns of rhythm, melody and harmony.","Music is both an art and a human cultural practice. Across societies, people create music using voices, instruments and digital tools, and use it for expression, ceremony, storytelling, celebration and shared identity."],sources:[["National Geographic — Sound","https://education.nationalgeographic.org/resource/sound/"]] },
{"id":"v7-stellar-evolution","cat":"space","title":"How Stars Evolve","deck":"A star's mass shapes its life cycle.","tags":"stars fusion supernova","body":["Stars form as gravity draws gas and dust together until fusion begins in the core. A star's mass determines its later evolution: Sun-like stars become red giants and leave white dwarfs, while massive stars may explode and leave neutron stars or black holes."],"sources":[["NASA — Stars","https://science.nasa.gov/universe/stars/"]]},
{"id":"v7-scientific-method","cat":"science","title":"The Scientific Method","deck":"How researchers test explanations using evidence.","tags":"hypothesis experiment observation evidence","body":["Science uses observation, measurement, reasoning and testing. Researchers form questions, make predictions and compare them with evidence. Methods vary across fields, but claims should be testable, transparent and open to revision."],"sources":[["Understanding Science — UC Berkeley","https://undsci.berkeley.edu/"]]},
{"id":"v7-immune-system","cat":"life","title":"The Human Immune System","deck":"A network of cells and organs that helps defend the body.","tags":"immunity antibodies infection","body":["The immune system recognises and responds to microbes. Innate immunity provides rapid broad responses; adaptive immunity uses specialised B and T cells. Immune memory can make later responses faster or stronger, which is the principle behind vaccination."],"sources":[["NIAID — Immune System Overview","https://www.niaid.nih.gov/research/immune-system-overview"]]},
{"id":"v7-rock-cycle","cat":"earth","title":"The Rock Cycle","deck":"Geological processes continually transform Earth's rocks.","tags":"igneous sedimentary metamorphic erosion","body":["Igneous rocks form as molten material cools; sedimentary rocks form from accumulated particles or chemical deposits; metamorphic rocks change under heat, pressure or fluids. Weathering, burial, melting and uplift connect these processes in many pathways."],"sources":[["USGS — The Rock Cycle","https://www.usgs.gov/special-topics/water-science-school/science/rock-cycle"]]},
{"id":"v7-silk-roads","cat":"history","title":"The Silk Roads","deck":"A changing network of routes connected communities across continents.","tags":"trade exchange silk routes","body":["The Silk Roads were a network of overland and maritime routes connecting cities and ports. Merchants moved silk, spices and other goods, while ideas, technologies and religious traditions also travelled. The routes changed as empires and trade centres shifted."],"sources":[["UNESCO — Silk Roads Programme","https://en.unesco.org/silkroad/"]]},
{"id":"v7-greek-myths","cat":"mythology","title":"Greek Mythology","deck":"Ancient stories about gods, heroes and the human condition.","tags":"zeus athena olympus myths","body":["Greek mythology includes stories about deities, heroes and origins. Stories about Zeus, Athena and Apollo varied across regions and periods. Myths survive in literature, sculpture and pottery, and were adapted by poets and communities rather than forming one fixed canon."],"sources":[["Theoi Greek Mythology","https://www.theoi.com/"]]},
{"id":"v7-internet","cat":"technology","title":"How the Internet Works","deck":"A global network that moves information using shared protocols.","tags":"internet tcp ip dns packets","body":["The internet connects independent networks using shared standards. Information is divided into packets that travel through routers. Internet Protocol supports addressing and routing; DNS translates domain names into network addresses. The World Wide Web is one service that uses the internet."],"sources":[["Internet Society — Internet Basics","https://www.internetsociety.org/internet/"]]},
{"id":"v7-deep-ocean","cat":"mysteries","title":"Exploring the Deep Ocean","deck":"Technology is revealing more about Earth's least accessible environments.","tags":"deep sea ocean exploration","body":["The deep ocean is difficult to study because of pressure, darkness and distance. Researchers use remotely operated vehicles, autonomous underwater vehicles and sonar to map seafloor landscapes and observe life. New discoveries expand scientific knowledge through careful investigation."],"sources":[["NOAA Ocean Exploration","https://oceanexplorer.noaa.gov/"]]},
{"id":"v7-motion-laws","cat":"physics","title":"Newton's Laws of Motion","deck":"Three principles connect forces with changes in motion.","tags":"inertia force acceleration mechanics","body":["Newton's first law says motion remains unchanged unless a net force acts. The second law relates net force to acceleration, commonly F = ma for constant mass. The third law says interacting objects exert forces equal in magnitude and opposite in direction."],"sources":[["OpenStax University Physics, Volume 1","https://openstax.org/details/books/university-physics-volume-1"]]},
{"id":"v7-reaction-basics","cat":"chemistry","title":"Understanding Chemical Reactions","deck":"Atoms rearrange as reactants become products.","tags":"reactants products bonds conservation","body":["Chemical reactions rearrange atoms and change how they are bonded. Balanced equations show the same number of each type of atom on both sides, reflecting conservation of matter. Temperature, concentration, surface area and catalysts can affect reaction rates."],"sources":[["OpenStax Chemistry 2e","https://openstax.org/details/books/chemistry-2e"]]},
{"id":"v7-statistics","cat":"mathematics","title":"Statistics and Data","deck":"Methods for describing data and drawing conclusions under uncertainty.","tags":"mean median sampling probability","body":["Statistics helps summarise data and reason about variation. The mean, median and range describe different features of a dataset. Unrepresentative samples can mislead; statistical inference estimates quantities or assesses hypotheses while accounting for uncertainty."],"sources":[["OpenStax Introductory Statistics","https://openstax.org/details/books/introductory-statistics"]]},
{"id":"v7-antibiotic-resistance","cat":"medicine","title":"Antibiotic Resistance","deck":"How bacteria can evolve ways to survive medicines.","tags":"bacteria antibiotics resistance infection","body":["Antibiotics treat bacterial infections, not viral infections. Resistance develops when bacteria acquire traits that let them survive exposure. Resistant bacteria can spread; inappropriate antibiotic use increases selection pressure. Infection prevention, vaccination, surveillance and responsible prescribing help address this challenge."],"sources":[["WHO — Antimicrobial Resistance","https://www.who.int/news-room/fact-sheets/detail/antimicrobial-resistance"]]},
{"id":"v7-memory-learning","cat":"psychology","title":"Learning and Memory","deck":"Experience changes the brain and supports memory formation.","tags":"learning memory attention retrieval","body":["Learning involves changes in knowledge or behaviour through experience. Memory includes encoding, retaining and retrieving information. Attention, prior knowledge, practice and sleep influence learning. Recall is reconstructive and can be affected by context and later information."],"sources":[["American Psychological Association — Memory","https://www.apa.org/topics/memory"]]},
{"id":"v7-latitude-longitude","cat":"geography","title":"Latitude and Longitude","deck":"A coordinate system for locating places on Earth's surface.","tags":"coordinates equator meridian mapping","body":["Latitude measures angular position north or south of the Equator; longitude measures position east or west of the Prime Meridian. Together they provide a global coordinate framework. Datums and map projections affect how locations are represented."],"sources":[["National Geographic Education — Latitude and Longitude","https://education.nationalgeographic.org/resource/latitude-and-longitude/"]]},
{"id":"v7-carbon-cycle","cat":"environment","title":"The Carbon Cycle","deck":"Carbon moves among atmosphere, oceans, land and living things.","tags":"carbon dioxide photosynthesis respiration climate","body":["Photosynthetic organisms take in carbon dioxide and build organic molecules. Respiration, decomposition and combustion return carbon to air or water; oceans also exchange carbon dioxide with the atmosphere. Human activities add carbon dioxide faster than natural processes currently remove it."],"sources":[["NASA Earth Observatory — The Carbon Cycle","https://earthobservatory.nasa.gov/features/CarbonCycle"]]},
{"id":"v7-bridge-engineering","cat":"engineering","title":"How Bridges Carry Loads","deck":"Bridge structures transfer forces safely into their foundations.","tags":"structures tension compression civil engineering","body":["A bridge transfers loads from its deck through structural elements to supports. Beam bridges resist bending, arches direct loads into compression, and suspension bridges use cables in tension. Engineers also consider wind, traffic, water, durability, inspection and maintenance."],"sources":[["American Society of Civil Engineers — Bridges","https://www.asce.org/topics/bridges"]]},
{"id":"v7-inflation","cat":"economics","title":"Inflation and Purchasing Power","deck":"Inflation is a sustained rise in the general level of prices.","tags":"prices purchasing power economy","body":["Inflation means the overall price level rises, so money buys less on average. Price indices track selected baskets. Inflation can be influenced by demand, production costs, supply disruptions and monetary conditions; households experience it differently according to spending patterns."],"sources":[["IMF — Inflation: Prices on the Rise","https://www.imf.org/en/Publications/fandd/issues/Series/Back-to-Basics/Inflation"]]},
{"id":"v7-logic","cat":"philosophy","title":"Logic and Good Reasoning","deck":"Logic examines how conclusions follow from premises.","tags":"reasoning arguments validity deduction","body":["An argument contains premises offered in support of a conclusion. A deductively valid argument has a conclusion that must be true if all premises are true; soundness also requires true premises. Inductive reasoning supports conclusions by degrees rather than certainty."],"sources":[["Stanford Encyclopedia of Philosophy — Logic","https://plato.stanford.edu/entries/logic-classical/"]]},
{"id":"v7-constitutions","cat":"civics","title":"Why Constitutions Matter","deck":"Constitutions establish the framework and limits of public power.","tags":"law rights government institutions","body":["A constitution establishes basic rules for a political system. It may define institutions, allocate powers, protect rights and set lawmaking procedures. Its effectiveness depends on institutions, political culture and public participation; constitutional safeguards aim to make government accountable."],"sources":[["Constitute Project — Comparative Constitutions","https://www.constituteproject.org/"]]},
{"id":"v7-soil-health","cat":"agriculture","title":"Soil Health and Sustainable Farming","deck":"Healthy soil supports crops, biodiversity and water storage.","tags":"soil organic matter erosion farming","body":["Soil contains minerals, organic matter, water, air and organisms. Maintaining soil cover, rotating crops and reducing erosion can protect soil, though suitable practices depend on local conditions. Because soil forms slowly, preventing degradation is important for long-term food production."],"sources":[["FAO — Soil Management","https://www.fao.org/soils-portal/soil-management/en/"]]},
{"id":"v7-poetry-reading","cat":"literature","title":"How to Read Poetry","deck":"Poems use sound, imagery and structure to shape meaning.","tags":"poetry metaphor imagery rhythm","body":["Poetry uses language in concentrated and often patterned ways. Rhythm, rhyme, repetition, imagery and line breaks create meaning and emotional effects. Close reading considers the speaker, word choices and structure. Forms vary widely across cultures and periods."],"sources":[["Poetry Foundation — Learn About Poetry","https://www.poetryfoundation.org/learn"]]},
{"id":"v7-design-principles","cat":"arts","title":"Principles of Visual Design","deck":"Balance, contrast and hierarchy organise visual information.","tags":"design balance contrast hierarchy","body":["Visual design combines line, shape, colour, texture, space and typography. Contrast highlights information; hierarchy guides attention; alignment and proximity show relationships; repetition creates consistency. Designers adapt these principles to purpose, audience, medium and accessibility needs."],"sources":[["Interaction Design Foundation — Design Principles","https://www.interaction-design.org/literature/topics/design-principles"]]},
{"id":"v7-fair-play","cat":"sports","title":"Rules and Fair Play in Sport","deck":"Shared rules make competition understandable and consistent.","tags":"sportsmanship referees rules competition","body":["Sporting rules define how a game is played and how points are scored. Officials interpret rules, while governing bodies update them. Fair play includes respect for opponents, teammates and officials; transparent standards help maintain trust in results."],"sources":[["International Olympic Committee — Integrity","https://olympics.com/ioc/integrity"]]},
{"id":"v7-passive-design","cat":"architecture","title":"Passive Design in Buildings","deck":"Orientation, shading and ventilation can improve comfort and efficiency.","tags":"architecture energy daylight ventilation","body":["Passive design uses a building's form, orientation and materials to respond to local climate. Shading, window placement, insulation, thermal mass and natural ventilation can reduce energy demand. The right combination depends on the site, climate and how the building is used."],"sources":[["U.S. Department of Energy — Energy-Efficient Home Design","https://www.energy.gov/energysaver/design"]]}
];
const labels={space:"SPACE & COSMOS",science:"SCIENCE",life:"LIFE & BIOLOGY",earth:"EARTH",history:"HISTORY",mythology:"MYTHOLOGY",technology:"TECHNOLOGY",mysteries:"MYSTERIES",physics:"PHYSICS",chemistry:"CHEMISTRY",mathematics:"MATHEMATICS",medicine:"MEDICINE & HEALTH",psychology:"PSYCHOLOGY",geography:"GEOGRAPHY",environment:"ENVIRONMENT",engineering:"ENGINEERING",economics:"ECONOMICS",philosophy:"PHILOSOPHY",civics:"CIVICS & SOCIETY",agriculture:"AGRICULTURE",literature:"LITERATURE",arts:"ARTS & DESIGN",sports:"SPORTS",architecture:"ARCHITECTURE"};
const grid=document.getElementById("enGrid"),search=document.getElementById("enSearch"),count=document.getElementById("enCount"),empty=document.getElementById("enEmpty"),filters=[...document.querySelectorAll("[data-category]")],modal=document.getElementById("enModal");
let active="all",lastTrigger=null;
document.getElementById("articleTotal").textContent=entries.length;
document.getElementById("domainTotal").textContent=Object.keys(labels).length;
function render(){const q=search.value.trim().toLowerCase();const shown=entries.filter(x=>(active==="all"||x.cat===active)&&(!q||(x.title+" "+x.deck+" "+x.tags+" "+x.body.join(" ")).toLowerCase().includes(q)));grid.innerHTML=shown.map(x=>'<button class="en-card" type="button" data-entry="'+x.id+'"><span class="en-card-meta"><span>'+labels[x.cat]+'</span><span>FILE / '+String(entries.indexOf(x)+1).padStart(3,"0")+'</span></span><h3>'+x.title+'</h3><p>'+x.deck+'</p><span class="en-card-open">OPEN ENCYCLOPAEDIA ENTRY ↗</span></button>').join("");count.textContent=String(shown.length).padStart(2,"0")+" ARTICLES";empty.hidden=shown.length!==0;grid.hidden=shown.length===0;grid.querySelectorAll("[data-entry]").forEach(b=>b.addEventListener("click",()=>openEntry(b.dataset.entry,b)));filters.forEach(b=>{const on=b.dataset.category===active;b.classList.toggle("selected",on);b.setAttribute("aria-pressed",String(on));});}
function openEntry(id,trigger){const x=entries.find(e=>e.id===id);if(!x)return;lastTrigger=trigger;document.getElementById("enModalMeta").textContent=labels[x.cat]+" / ASTRALORE KNOWLEDGE INDEX";document.getElementById("enModalTitle").textContent=x.title;document.getElementById("enModalDeck").textContent=x.deck;const body=document.getElementById("enModalBody");body.innerHTML=x.body.map(p=>"<p>"+p+"</p>").join("");document.getElementById("enModalSources").innerHTML=x.sources.map(s=>'<li><a href="'+s[1]+'" target="_blank" rel="noopener noreferrer">'+s[0]+' ↗</a></li>').join("");modal.hidden=false;document.body.style.overflow="hidden";document.getElementById("enModalClose").focus();}
function closeEntry(){if(modal.hidden)return;modal.hidden=true;document.body.style.overflow="";if(lastTrigger)lastTrigger.focus();lastTrigger=null;}
filters.forEach(b=>b.addEventListener("click",()=>{active=b.dataset.category;render();}));search.addEventListener("input",render);document.getElementById("enClear").addEventListener("click",()=>{search.value="";render();search.focus();});document.getElementById("enReset").addEventListener("click",()=>{active="all";search.value="";render();});document.getElementById("enModalClose").addEventListener("click",closeEntry);document.getElementById("enRelated").addEventListener("click",closeEntry);modal.addEventListener("click",e=>{if(e.target===modal)closeEntry();});document.addEventListener("keydown",e=>{if(modal.hidden)return;if(e.key==="Escape"){closeEntry();return;}if(e.key==="Tab"){const f=[...modal.querySelectorAll("button,a[href]")].filter(x=>x.getClientRects().length);if(!f.length)return;const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});render();